INSERT INTO `content_details` VALUES (1,1,1,'{\"title\":\"NLP GROUP\",\"sub_title\":\"Vietnam\'s Leading Green Infrastructure & Real Estate Investment Platform\",\"another_sub_title\":\"WITH REAL EARNING\",\"short_description\":\"<p>Buy shares of real estate properties, earn monthly income, and be part of Vietnam\'s fastest-growing EV infrastructure ecosystem.<\\/p>\",\"button_name\":\"Start Exploring\"}','2024-10-28 07:18:16','2024-10-28 07:18:16'),(3,2,1,'{\"title\":\"Passive Income\",\"short_details\":\"Earn rental income from premium Vietnamese real estate properties quarterly.\"}','2024-10-28 07:37:09','2024-10-28 07:37:09'),(5,3,1,'{\"title\":\"Secure & Transparent\",\"short_details\":\"All investments are legally registered under MST 0316942991 and compliant with Vietnamese law.\"}','2024-10-28 07:38:07','2024-10-28 07:38:07'),(7,4,1,'{\"title\":\"EV Infrastructure\",\"short_details\":\"Invest in Vietnam\'s green EV charging network — 14,000 charging points nationwide.\"}','2024-10-28 07:50:20','2024-10-28 07:50:20'),(9,5,1,'{\"title\":\"24\\/7 Support\",\"short_details\":\"Our dedicated team is available around the clock to assist you.\"}','2024-10-28 07:51:02','2024-10-28 07:51:02'),(11,6,1,'{\"title\":\"ABOUT NLP GROUP\",\"sub_title\":\"Welcome to NLP Group\",\"short_title\":\"Building Vietnam\'s Green Future Together\",\"short_description\":\"<p>NLP Group Joint Stock Company (MST: 0316942991) is Vietnam\'s leading conglomerate in green infrastructure and real estate investment. With charter capital of 1,172.5 billion VND, we operate the CD Restop highway rest stop system (34 provinces), the CD GO electric vehicle ecosystem, the GOMO community commerce platform, and a nationwide EV charging network with 14,000 charging points. We are headquartered at No.16, D1 Street, Mega Village Khang Dien, Phu Huu Ward, Thu Duc City, Ho Chi Minh City, Vietnam.<\\/p>\"}','2024-10-28 07:55:22','2024-10-28 07:55:22'),(13,7,1,'{\"title\":\"FEATURED PROPERTIES\",\"sub_title\":\"Premium Investment Properties\"}','2024-10-28 07:59:04','2024-10-28 07:59:04'),(15,8,1,'{\"title\":\"INVESTOR TESTIMONIALS\",\"sub_title\":\"What Our Investors Say\"}','2024-10-28 08:02:35','2024-10-28 08:02:35'),(17,9,1,'{\"title\":\"Latest Properties\",\"sub_title\":\"Latest Investment Properties\"}','2024-10-28 08:04:31','2024-10-28 08:04:31'),(19,10,1,'{\"title\":\"ANYONE CAN INVEST WITH NLP GROUP\",\"sub_title\":\"You Invest. NLP Group Does The Rest\"}','2024-10-28 08:05:45','2024-10-28 08:05:45'),(21,11,1,'{\"title\":\"Subscribe to Our Newsletter\",\"sub_title\":\"GET EXCLUSIVE INVESTMENT INSIGHTS\"}','2024-10-28 08:12:58','2024-10-28 08:12:58'),(25,13,1,'{\"title\":\"FREQUENTLY ASKED QUESTIONS\",\"sub_title\":\"We\'ve Got Answers\",\"short_details\":\"<p>Find answers to the most common questions about investing with NLP Group — Vietnam\'s leading conglomerate in green infrastructure and real estate.<\\/p>\"}','2024-10-28 08:16:26','2024-10-28 08:16:26'),(27,14,1,'{\"title\":\"What is NLP Group?\",\"description\":\"<p>NLP Group Joint Stock Company (MST: 0316942991) is Vietnam\'s leading conglomerate operating in green infrastructure, EV charging, real estate investment, and community commerce. We manage the CD Restop rest stop system (34 provinces), the CD GO EV ecosystem, and the GOMO platform, backed by a charter capital of 1,172.5 billion VND.<\\/p>\"}','2024-10-28 08:22:52','2024-10-28 08:22:52'),(28,15,1,'{\"title\":\"Who can invest with NLP Group?\",\"description\":\"<p>Anyone aged 18 and above can invest with NLP Group — individuals and institutions alike, both domestic and international investors. Our platform accepts flexible investment amounts to suit every budget, starting from the minimum deposit threshold.<\\/p>\"}','2024-10-28 08:23:12','2024-10-28 08:23:12'),(29,16,1,'{\"title\":\"How are investment returns calculated?\",\"description\":\"<p>Returns are calculated based on the property or project value, the investment plan selected, and the profit percentage agreed upon. NLP Group offers both fixed and range-based profit plans, with returns distributed at regular intervals — daily, weekly, or monthly — depending on the plan.<\\/p>\"}','2024-10-28 08:23:27','2024-10-28 08:23:27'),(30,17,1,'{\"title\":\"Is my investment legally protected?\",\"description\":\"<p>Yes. NLP Group is a legally registered company in Vietnam under business registration number 0316942991, headquartered at No.16, D1 Street, Mega Village Khang Dien, Phu Huu Ward, Thu Duc City, Ho Chi Minh City. All investments are backed by real, tangible assets and comply with Vietnamese financial regulations.<\\/p>\"}','2024-10-28 08:23:41','2024-10-28 08:23:41'),(35,18,1,'{\"heading\":\"GET IN TOUCH\",\"sub_heading\":\"Let\'s Talk About Your Investment\",\"title\":\"Our Headquarters\",\"address\":\"No.16, D1 Street, Mega Village Khang Dien, Phu Huu Ward, Thu Duc City, Ho Chi Minh City, Vietnam\",\"email\":\"phuc.luungoc@mbbank.com.vn\",\"phone\":\"+84 936 611 163\",\"footer_short_details\":\"<p>NLP Group Joint Stock Company — Vietnam\'s leading green infrastructure & real estate investment platform. MST: 0316942991. Charter capital: 1,172.5 billion VND.<\\/p>\"}','2024-10-28 08:30:23','2024-10-28 08:30:23'),(37,19,1,'{\"title\":\"NLP GROUP IS UPGRADING\",\"sub_title\":\"We are improving our platform to serve you better!\",\"short_description\":\"<p>Our team is working hard to upgrade NLP Group\'s investment platform. We will be back shortly with exciting new features. Thank you for your patience.<\\/p>\"}','2024-10-28 08:33:17','2024-11-10 02:25:45'),(39,20,1,'{\"heading\":\"OUR BLOGS\",\"sub_heading\":\"Latest News & Insights from NLP Group\"}','2024-10-28 08:34:04','2024-10-28 08:34:04'),(41,21,1,'{\"name\":\"Nguyen Thi Lan\",\"designation\":\"Property Investor, Hanoi\",\"description\":\"<p>NLP Group gave me the opportunity to invest in premium real estate without needing massive capital. My returns have been consistent every quarter.<\\/p>\"