21,'{\"title\":\"Thu Nhập Thụ Động\",\"short_details\":\"Nhận lợi nhuận định kỳ từ danh mục bất động sản cao cấp và hạ tầng EV — phân phối hàng quý, minh bạch và đúng hạn.\"}','2026-10-08 14:17:12','2026-10-08 14:17:12'),(173,3,21,'{\"title\":\"An Toàn & Minh Bạch\",\"short_details\":\"Mọi khoản đầu tư đều gắn với tài sản thực, đăng ký pháp lý đầy đủ theo MST 0316942991, báo cáo định kỳ cho nhà đầu tư và cơ quan quản lý.\"}','2026-10-08 14:17:12','2026-10-08 14:17:12'),(174,4,21,'{\"title\":\"Hạ Tầng Xanh — Chuẩn Cam Kết\",\"short_details\":\"Đầu tư vào mạng lưới sạc EV và trạm dừng chân chuẩn «5 CÓ» — 14.000 điểm sạc vệ tinh, 34 tỉnh thành, tích hợp năng lượng mặt trời tại điểm.\"}','2026-10-08 14:17:12','2026-10-08 14:17:12'),(175,5,21,'{\"title\":\"Hỗ Trợ Nhà Đầu Tư 24/7\",\"short_details\":\"Đội ngũ chuyên gia đầu tư và pháp lý luôn sẵn sàng — tư vấn trực tiếp, báo cáo minh bạch và đồng hành dài hạn cùng bạn.\"}','2026-10-08 14:17:12','2026-10-08 14:17:12'),(176,81,21,'{\"title\":\"NLP Energy\",\"short_details\":\"Điện mặt trời áp mái, lưu trữ BESS, quản lý EMS và tổng thầu EPC — giải pháp năng lượng xanh toàn diện.\"}','2026-10-08 14:17:12','2026-10-08 14:17:12'),(177,82,21,'{\"title\":\"NLP EV Charging\",\"short_details\":\"Hạ tầng trạm sạc xe điện AC\\/DC thông minh, chuẩn OCPP, mô hình nhượng quyền trên toàn quốc.\"}','2026-10-08 14:17:12','2026-10-08 14:17:12'),(178,83,21,'{\"title\":\"NLP Technology\",\"short_details\":\"Phần mềm, IoT, ERP\\/CRM, Cloud và chuyển đổi số — nền tảng công nghệ cho doanh nghiệp hiện đại.\"}','2026-10-08 14:17:12','2026-10-08 14:17:12'),(179,84,21,'{\"title\":\"NLP ESG & Carbon\",\"short_details\":\"MRV số, tín chỉ carbon, trồng rừng bền vững và lộ trình Net Zero cho doanh nghiệp.\"}','2026-10-08 14:17:12','2026-10-08 14:17:12'),(180,6,21,'{\n  \"title\": \"VỀ TẬP ĐOÀN NLP\",\n  \"sub_title\": \"Kiến Tạo Hạ Tầng An Sinh — Đầu Tư Bền Vững\",\n  \"short_title\": \"Chuyển đổi số gặp chuyển đổi xanh\",\n  \"short_description\": \"<p>Công ty Cổ phần Tập đoàn NLP (MST: 0316942991) là tập đoàn hàng đầu Việt Nam trong lĩnh vực hạ tầng xanh và đầu tư bất động sản. Với vốn điều lệ <strong>1.172,5 tỷ VNĐ</strong>, chúng tôi phát triển và vận hành hệ thống trạm dừng chân an sinh CD Restop trên 34 tỉnh thành, hệ sinh thái xe điện CD GO, nền tảng thương mại an sinh GOMO và mạng lưới sạc EV toàn quốc với 14.000 điểm sạc. Định hướng <em>hạ tầng đi trước — an sinh là phần lõi</em>.</p>\"\n}','2026-10-08 14:17:12','2026-10-08 14:17:12'),(181,51,21,'{\"title\":\"về nlp group\",\"sub_title\":\"Kiến tạo hệ sinh thái đổi mới bền vững\",\"short_title\":\"Năng lượng xanh • Xe điện • Công nghệ • AI • Phát triển bền vững\",\"short_description\":\"<p>NLP Group là doanh nghiệp phát triển hệ sinh thái công nghệ và năng lượng xanh, tập trung vào 5 lĩnh vực: Năng lượng tái tạo, Hạ tầng xe điện, Công nghệ phần mềm, Trí tuệ nhân tạo và Phát triển bền vững & tín chỉ carbon.<\\/p><p>Chúng tôi xây dựng giải pháp thông minh, kết nối công nghệ với năng lượng sạch, giúp doanh nghiệp nâng cao hiệu quả vận hành và thúc đẩy chuyển đổi xanh tại Việt Nam.<\\/p>\",\"background_title\":\"Công nghệ tạo giá trị. Năng lượng tạo tương lai.\",\"background_short_title\":\"Bền vững tạo thịnh vượng — NLP Group\"}','2026-10-08 14:17:12','2026-10-08 14:17:12'),(182,7,21,'{\"title\":\"BẤT ĐỘNG SẢN NỔI BẬT\",\"sub_title\":\"Danh Mục Đầu Tư Cao Cấp\"}','2026-10-08 14:17:12','2026-10-08 14:17:12'),(183,52,21,'{\"title\":\"Dự án nổi bật\",\"sub_title\":\"Danh mục dự án đầu tư NLP Group\"}','2026-10-08 14:17:12','2026-10-08 14:17:12'),(184,8,21,'{\n  \"title\": \"NHÀ ĐẦU TƯ NÓI GÌ\",\n  \"sub_title\": \"Lời Chứng Thực Về Sự Tin Tưởng & Minh Bạch\"\n}','2026-10-08 14:17:12','2026-10-08 14:17:12'),(185,53,21,'{\"title\":\"đối tác & khách hàng\",\"sub_title\":\"Họ nói gì về NLP Group?\",\"short_description\":\"Hơn 150 dự án triển khai thành công, NLP Group được tin tưởng bởi hàng nghìn nhà đầu tư và đối tác doanh nghiệp trên toàn Việt Nam.\",\"background_title\":\"Uy tín — Đổi mới — Bền vững — Hợp tác\"}','2026-10-08 14:17:12','2026-10-09 00:55:28'),(186,54,21,'{\"name\":\"Nguyễn Thị Lan\",\"designation\":\"Nhà đầu tư BĐS, Hà Nội\",\"review\":\"5\",\"description\":\"<p>Tập đoàn NLP giúp tôi tiếp cận bất động sản cao cấp mà không cần vốn lớn. Lợi nhuận ổn định, phân phối đúng hạn mỗi quý. Đây là cách đầu tư thông minh nhất tôi từng thực hiện.</p>\"}','2026-10-08 14:17:12','2026-10-08 14:17:12'),(187,55,21,'{\"name\":\"Trần Minh Đức\",\"designation\":\"Doanh nhân, TP. Hồ Chí Minh\",\"review\":\"5\",\"description\":\"<p>Tính minh bạch và tuân thủ pháp lý của Tập đoàn NLP là điều tôi đánh giá cao nhất. Mọi tài liệu đều có thể xác minh theo MST 0316942991 — tôi đầu tư với tâm lý hoàn toàn an tâm.</p>\"}','2026-10-08 14:17:12','2026-10-08 14:17:12'),(188,56,21,'{\"name\":\"Lê Hoàng Nam\",\"designation\":\"Doanh nhân công nghệ, Đà Nẵng\",\"review\":\"5\",\"description\":\"<p>Đầu tư vào hạ tầng EV và trạm dừng chân CD Restop qua Tập đoàn NLP là quyết định tiên phong. Thị trường EV Việt Nam đang bùng nổ và tôi đang nắm giữ một phần của tương lai đó.</p>\"}','2026-10-08 14:17:12','2026-10-08 14:17:12'),(189,57,21,'{\"name\":\"Phạm Thị Thu\",\"designation\":\"Giáo viên, Cần Thơ\",\"review\":\"4\",\"description\":\"<p>Dù bắt đầu với khoản đầu tư nhỏ, tôi vẫn nhận được lợi nhuận đáng tin cậy và đều đặn. Đội ngũ hỗ trợ nhiệt tình, giải thích rõ ràng từng bước — rất phù hợp cho người mới bắt đầu.</p>\"}','2026-10-08 14:17:12','2026-10-08 14:17:12'),(190,58,21,'{\"name\":\"Đỗ Quang Vinh\",\"designation\":\"Tư vấn tài chính, Bình Dương\",\"review\":\"5\",\"description\":\"<p>Tập đoàn NLP nổi bật nhờ tài sản thực và nền tảng pháp lý vững chắc. Đặc biệt phù hợp cho nhà đầu tư dài hạn muốn xây dựng danh mục đa dạng từ BĐS đến hạ tầng xanh.</p>\"}','2026-10-08 14:17:12','2026-10-08 14:17:12'),(191,21,21,'{\"name\":\"Nguyễn Thị Lan\",\"designation\":\"Nhà đầu tư BĐS, Hà Nội\",\"review\":\"5\",\"description\":\"<p>Tập đoàn NLP giúp tôi 