INSERT INTO `pages` VALUES (1,'home','/','light',NULL,'Trang Chủ','NLP Group | Tổng Thầu EPC & Nhà Phân Phối Điện Mặt Trời Uy Tín','[\"điện mặt trời\",\"tổng thầu EPC\",\"phân phối thiết bị quang điện\",\"tấm pin năng lượng mặt trời\",\"biến tần inverter\",\"NLP Group\",\"điện mặt trời áp mái\",\"giải pháp năng lượng sạch\"]','NLP Group là tổng thầu EPC và nhà phân phối chính thức thiết bị điện mặt trời đạt chuẩn ISO 9001, ISO 14001, ISO 45001. Cung cấp giải pháp năng lượng tối ưu, an toàn và hiệu suất cao cho doanh nghiệp và hộ gia đình.','seo/8QnArsj4wdvtGksUEpwhoK2y4FDo8O.webp','local',NULL,'local',0,1,0,1,'2024-10-29 03:48:00','2026-10-13 04:06:27','Khám phá giải pháp điện mặt trời toàn diện cùng NLP Group - Tổng thầu EPC và nhà phân phối thiết bị quang điện chính hãng, chứng nhận ISO và giấy phép điện lực toàn diện.','index,follow'),(2,'about','about','light',NULL,'Giới thiệu','Giới Thiệu NLP Group | Đơn Vị Tổng Thầu EPC & Phân Phối Năng Lượng Uy Tín','[\"về NLP Group\",\"năng lực tổng thầu EPC\",\"hồ sơ năng lực NLP Group\",\"chứng nhận ISO\",\"nhà phân phối thiết bị solar\"]','Tìm hiểu về NLP Group - Tổng thầu EPC và nhà phân phối điện mặt trời hàng đầu. Sở hữu chứng nhận ISO 9001, 14001, 45001 cùng giấy phép xây dựng và hoạt động điện lực chính quy.',NULL,NULL,'pagesImage/gdb1y2JEMSM0VXKdslclklPki3KukS.webp','local',1,1,0,1,'2024-10-30 01:33:53','2026-10-13 04:06:27','Tập đoàn NLP — đối tác đầu tư hạ tầng xanh và bất động sản uy tín hàng đầu Việt Nam.','follow'),(3,'faq','faq','light',NULL,'Câu hỏi thường gặp','Hỏi Đáp Về Điện Mặt Trời & Dịch Vụ EPC | NLP Group','[\"hỏi đáp điện mặt trời\",\"chi phí lắp điện mặt trời\",\"thủ tục đấu nối EVN\",\"bảo hành pin mặt trời\",\"FAQ năng lượng mặt trời\"]','Tổng hợp giải đáp các câu hỏi thường gặp về kỹ thuật, thủ tục đấu nối EVN, chi phí lắp đặt và chính sách bảo hành hệ thống điện mặt trời tại NLP Group.',NULL,NULL,'pagesImage/L9nuFi1euEomLa9d3z0mHNiIbVcYdn.webp','local',1,1,0,1,'2024-10-30 02:28:18','2026-10-13 04:06:27','Giải đáp mọi câu hỏi về đầu tư cùng NLP Group — tập đoàn hàng đầu Việt Nam.',NULL),(4,'contact','contact','light',NULL,'Liên hệ','Liên Hệ NLP Group | Tư Vấn Kỹ Thuật & Báo Giá Điện Mặt Trời','[\"liên hệ NLP Group\",\"báo giá điện mặt trời\",\"tư vấn EPC solar\",\"khảo sát áp mái\",\"hỗ trợ kỹ thuật điện mặt trời\",\"tổng thầu năng lượng\"]','Liên hệ NLP Group ngay hôm nay để nhận tư vấn kỹ thuật chuyên sâu, khảo sát công trình và báo giá giải pháp tổng thầu EPC điện mặt trời trọn gói trên toàn quốc.',NULL,NULL,'pagesImage/V0vUebCDEBbxjIqZg7I9KDR6l7PuhL.webp','local',1,1,0,1,'2024-10-30 02:44:44','2026-10-13 04:06:27','Kết nối với đội ngũ kỹ sư NLP Group để nhận giải pháp thiết kế, thi công và phân phối thiết bị điện mặt trời tối ưu nhất cho dự án của bạn.','index,follow'),(5,'Blog','blog','light',NULL,'Tin tức','Bản Tin Năng Lượng Mặt Trời & Kiến Thức Kỹ Thuật | NLP Group','[\"tin tức điện mặt trời\",\"kiến thức quang điện\",\"xu hướng năng lượng tái tạo\",\"cẩm nang EPC solar\",\"kinh nghiệm lắp điện mặt trời\"]','Cập nhật tin tức thị trường năng lượng tái tạo, xu hướng công nghệ quang điện mới nhất và cẩm nang vận hành bảo dưỡng (O&M) từ chuyên gia NLP Group.',NULL,NULL,'pagesImage/fLjn951aV2RFxAJf7drOYfo0aumZLh.webp','local',1,1,2,1,'2024-10-30 03:19:08','2026-10-13 04:06:27','Blog NLP Group — cập nhật kiến thức đầu tư, EV, bất động sản và hạ tầng an sinh Việt Nam.','index,follow'),(6,'privacy policy','privacy-policy','light',NULL,'Chính sách bảo mật','Chính Sách Bảo Mật | NLP Group - Cam Kết Bảo Vệ Dữ Liệu','[\"chính sách bảo mật\",\"bảo mật thông tin\",\"an toàn dữ liệu\",\"NLP Group bảo mật\",\"quy định bảo mật\"]','Chính sách bảo mật thông tin khách hàng và đối tác của NLP Group. Chúng tôi cam kết bảo vệ dữ liệu cá nhân, thông tin dự án theo đúng quy chuẩn pháp lý hiện hành.',NULL,NULL,'/pjdy0WjvvvkzAZxuMdVJyqVgMAFp8M.webp','local',1,1,0,1,'2024-10-30 07:11:08','2026-10-13 04:06:27','Tìm hiểu cách NLP Group thu thập, bảo vệ và xử lý thông tin cá nhân